css:
.ink-checkbox {
  position: relative;
  width: 72px;
  height: 72px;
  display: block;
  cursor: pointer;
}

.ink-checkbox input {
  display: none;
}

.ink-box {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border: 2px solid #111;
  border-radius: 19px;
  background: #eee;
  transition:
    transform 0.35s cubic-bezier(0.2, 0.8, 0.2, 1),
    border-radius 0.55s ease,
    background 0.4s ease;
}

.ink {
  position: absolute;
  width: 18px;
  height: 18px;
  left: 50%;
  top: 50%;
  border-radius: 48% 52% 45% 55%;
  background: #111;
  transform: translate(-50%, -50%) scale(0);
  transition:
    transform 0.72s cubic-bezier(0.16, 1, 0.3, 1),
    border-radius 0.5s ease;
}

.ink::before {
  content: "";
  position: absolute;
  inset: 0;
  border: 2px solid #111;
  border-radius: 50%;
  transform: scale(0.65);
  opacity: 0;
  transition:
    transform 0.6s ease,
    opacity 0.3s ease;
}

.ripple {
  position: absolute;
  width: 22px;
  height: 22px;
  left: 50%;
  top: 50%;
  border: 2px solid #111;
  border-radius: 50%;
  transform: translate(-50%, -50%) scale(0);
  opacity: 0;
  transition:
    transform 0.7s cubic-bezier(0.16, 1, 0.3, 1),
    opacity 0.5s ease;
}

.ink-check {
  position: absolute;
  width: 26px;
  height: 14px;
  left: 50%;
  top: 50%;
  border-left: 4px solid #eee;
  border-bottom: 4px solid #eee;
  transform: translate(-50%, -50%) rotate(-45deg) scale(0);
  transform-origin: center;
  opacity: 0;
  clip-path: inset(0 100% 0 0);
  transition:
    clip-path 0.45s cubic-bezier(0.65, 0, 0.35, 1),
    transform 0.45s cubic-bezier(0.16, 1, 0.3, 1),
    opacity 0.2s ease;
}

.drop {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--size);
  height: var(--size);
  border-radius: 50%;
  background: #111;
  transform: translate(-50%, -50%) translate(0, 0) scale(0);
  opacity: 0;
  transition:
    transform 0.65s cubic-bezier(0.16, 1, 0.3, 1),
    opacity 0.25s ease;
}

.drop-one {
  --x: -27px;
  --y: -23px;
  --size: 5px;
  transition-delay: 0.03s;
}
.drop-two {
  --x: 29px;
  --y: -16px;
  --size: 4px;
  transition-delay: 0.06s;
}
.drop-three {
  --x: 25px;
  --y: 28px;
  --size: 7px;
  transition-delay: 0.09s;
}
.drop-four {
  --x: -29px;
  --y: 25px;
  --size: 4px;
  transition-delay: 0.12s;
}
.drop-five {
  --x: 8px;
  --y: -31px;
  --size: 3px;
  transition-delay: 0.15s;
}
.drop-six {
  --x: -9px;
  --y: 31px;
  --size: 3px;
  transition-delay: 0.18s;
}

.ink-checkbox input:checked + .ink-box {
  background: #111;
  border-color: #111;
  border-radius: 21px;
}

.ink-checkbox input:checked + .ink-box .ink {
  transform: translate(-50%, -50%) scale(5.2);
  border-radius: 43% 57% 52% 48%;
}

.ink-checkbox input:checked + .ink-box .ink::before {
  transform: scale(1.35);
  opacity: 0.18;
}

.ink-checkbox input:checked + .ink-box .ripple {
  transform: translate(-50%, -50%) scale(3.8);
  opacity: 0;
}

.ink-checkbox input:checked + .ink-box .drop {
  transform: translate(-50%, -50%) translate(var(--x), var(--y)) scale(1);
  opacity: 1;
}

.ink-checkbox input:checked + .ink-box .ink-check {
  opacity: 1;
  clip-path: inset(0 0 0 0);
  transform: translate(-50%, -50%) rotate(-45deg) scale(1);
  transition-delay: 0.28s;
}

.ink-checkbox:hover .ink-box {
  transform: scale(1.045);
}

.ink-checkbox:hover .ink {
  transform: translate(-50%, -50%) scale(0.65);
}

.ink-checkbox:active .ink-box {
  transform: scale(0.91);
}
